"""Dump run-level formatting of key paragraphs + docDefaults + sectPr positions."""
from docx import Document
from docx.oxml.ns import qn
from lxml import etree

doc = Document('template.docx')
body = doc.element.body

def dump_para(i, elem, label):
    text = ''.join(t.text or '' for t in elem.findall('.//' + qn('w:t')))
    print(f'--- P{i:03d} [{label}] text={text!r}')
    pPr = elem.find(qn('w:pPr'))
    if pPr is not None:
        print('  pPr:', etree.tostring(pPr, pretty_print=False).decode()[:500])
    for r_i, r in enumerate(elem.findall(qn('w:r'))):
        rPr = r.find(qn('w:rPr'))
        t = ''.join(tt.text or '' for tt in r.findall(qn('w:t')))
        print(f'  run{r_i}: text={t!r}')
        if rPr is not None:
            print('    rPr:', etree.tostring(rPr).decode()[:400])

targets = {
    9: '报告题目', 10: '课程名称', 17: '实验名称', 18: '一、实验目的',
    19: 'empty-after-目的', 21: '二、实验材料', 24: '三、内容及原理',
    27: '四、步骤', 30: '五、结果', 31: 'empty', 32: 'last-empty',
}
pi = -1
for i, elem in enumerate(body):
    if elem.tag == qn('w:p'):
        pi += 1
        if pi in targets:
            # check sectPr in pPr
            pPr = elem.find(qn('w:pPr'))
            has_sect = pPr is not None and pPr.find(qn('w:sectPr')) is not None
            dump_para(i, elem, targets[pi] + (' +SECTBREAK' if has_sect else ''))

print('\n=== docDefaults ===')
styles_el = doc.styles.element
dd = styles_el.find(qn('w:docDefaults'))
if dd is not None:
    print(etree.tostring(dd, pretty_print=True).decode()[:1500])

print('\n=== default paragraph style ===')
try:
