{"file_path": "C:\Users\UserX\.zcode\workspace\default\vi_report\inspect_clean.py", "content": "# -*- coding: utf-8 -*-
"""Clean formatting dump: only essential rPr/pPr attributes."""
from docx import Document
from docx.oxml.ns import qn

doc = Document('template.docx')
body = doc.element.body

W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'

def rpr_summary(rPr):
    if rPr is None:
        return 'None'
    parts = []
    for child in rPr:
        tag = child.tag.replace(W, 'w:')
        attrs = {k.replace(W, 'w:'): v for k, v in child.attrib.items()}
        parts.append(f'{tag}{attrs}')
    return ' | '.join(parts)

def ppr_summary(pPr):
    if pPr is None:
        return 'None'
    parts = []
    for child in pPr:
        tag = child.tag.replace(W, 'w:')
        if tag == 'w:sectPr':
            parts.append('w:sectPr!')
            continue
        attrs = {k.replace(W, 'w:'): v for k, v in child.attrib.items()}
        parts.append(f'{tag}{attrs}')
    return ' | '.join(parts)

pi = -1
for i, elem in enumerate(body):
    if elem.tag != qn('w:p'):
        continue
    pi += 1
    text = ''.join(t.text or '' for t in elem.findall('.//' + qn('w:t')))
    pPr = elem.find(qn('w:pPr'))
    print(f'P{pi:03d}(body{i:02d}) pPr=[{ppr_summary(pPr)}]')
    print(f'       text={text!r}')
    for r_i, r in enumerate(elem.findall(qn('w:r'))):
        rPr = r.find(qn('w:rPr'))
        t = ''.join(tt.text or '' for tt in r.findall(qn('w:t')))
        print(f'   run{r_i}: {t!r} rPr=[{rpr_summary(rPr)}]')
"}

